      "arFull": "وَاِذَا لَقُوا الَّذِیْنَ اٰمَنُوْا قَالُوْۤا اٰمَنَّا ۖۚ وَاِذَا خَلَوْا اِلٰی شَیٰطِیْنِهِمْ ۙ قَالُوْۤا اِنَّا مَعَكُمْ ۙ اِنَّمَا نَحْنُ مُسْتَهْزِءُوْنَ ۟",
