      "arFull": "مَثَلُهُمْ كَمَثَلِ الَّذِی اسْتَوْقَدَ نَارًا ۚ فَلَمَّاۤ اَضَآءَتْ مَا حَوْلَهٗ ذَهَبَ اللّٰهُ بِنُوْرِهِمْ وَتَرَكَهُمْ فِیْ ظُلُمٰتٍ لَّا یُبْصِرُوْنَ ۟",
