      "number": 19,
      "arFull": "اَوْ كَصَیِّبٍ مِّنَ السَّمَآءِ فِیْهِ ظُلُمٰتٌ وَّرَعْدٌ وَّبَرْقٌ ۚ یَجْعَلُوْنَ اَصَابِعَهُمْ فِیْۤ اٰذَانِهِمْ مِّنَ الصَّوَاعِقِ حَذَرَ الْمَوْتِ ؕ وَاللّٰهُ مُحِیْطٌ بِالْكٰفِرِیْنَ ۟",
      "ur": "یا آسمانی برسات کی طرح جس میں اندھیریاں اور گرج اور بجلی ہو، موت سے ڈر کر کڑاکے کی وجہ سے اپنی انگلیاں اپنے کانوں میں ڈال لیتے ہیں۔ اور اللہ تعالیٰ کافروں کو گھیرنے واﻻ ہے۔",
      "en": "Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allāh is encompassing[14] of the disbelievers.",
