      "arFull": "یَكَادُ الْبَرْقُ یَخْطَفُ اَبْصَارَهُمْ ؕ كُلَّمَاۤ اَضَآءَ لَهُمْ مَّشَوْا فِیْهِ ۙۗ وَاِذَاۤ اَظْلَمَ عَلَیْهِمْ قَامُوْا ؕ وَلَوْ شَآءَ اللّٰهُ لَذَهَبَ بِسَمْعِهِمْ وَاَبْصَارِهِمْ ؕ اِنَّ اللّٰهَ عَلٰی كُلِّ شَیْءٍ قَدِیْرٌ ۟۠",
      "ur": "قریب ہے کہ بجلی ان کی آنکھیں اُچک لے جائے، جب ان کے لئے روشنی کرتی ہے تو اس میں چلتے پھرتے ہیں اور جب ان پر اندھیرا کرتی ہے تو کھڑے ہوجاتے ہیں[1] اور اگر اللہ تعالیٰ چاہے تو ان کے کانوں اور آنکھوں کو بیکار کردے[2]۔ یقیناً اللہ تعالیٰ ہر چیز پر قدرت رکھنے واﻻ ہے",
