      "arFull": "قَالُوْا سُبْحٰنَكَ لَا عِلْمَ لَنَاۤ اِلَّا مَا عَلَّمْتَنَا ؕ اِنَّكَ اَنْتَ الْعَلِیْمُ الْحَكِیْمُ ۟",
