      "ur": "اللہ تعالیٰ نے (حضرت) آدم ﴿علیہ السلام﴾ سے فرمایا تم ان کے نام بتا دو۔ جب انہوں نے بتا دیئے تو فرمایا کہ کیا میں نے تمہیں (پہلے ہی) نہ کہا تھا کہ زمین اور آسمانوں کا غیب میں ہی جانتا ہوں اور میرے علم میں ہے جو تم ﻇاہر کر رہے ہو اور جو تم چھپاتے تھے۔[1]",
