      "arFull": "وَاِذْ قَالَ مُوْسٰی لِقَوْمِهٖ یٰقَوْمِ اِنَّكُمْ ظَلَمْتُمْ اَنْفُسَكُمْ بِاتِّخَاذِكُمُ الْعِجْلَ فَتُوْبُوْۤا اِلٰی بَارِىِٕكُمْ فَاقْتُلُوْۤا اَنْفُسَكُمْ ؕ ذٰلِكُمْ خَیْرٌ لَّكُمْ عِنْدَ بَارِىِٕكُمْ ؕ فَتَابَ عَلَیْكُمْ ؕ اِنَّهٗ هُوَ التَّوَّابُ الرَّحِیْمُ ۟",
