      "arFull": "وَاِذْ قُلْتُمْ یٰمُوْسٰی لَنْ نَّصْبِرَ عَلٰی طَعَامٍ وَّاحِدٍ فَادْعُ لَنَا رَبَّكَ یُخْرِجْ لَنَا مِمَّا تُنْۢبِتُ الْاَرْضُ مِنْ بَقْلِهَا وَقِثَّآىِٕهَا وَفُوْمِهَا وَعَدَسِهَا وَبَصَلِهَا ؕ قَالَ اَتَسْتَبْدِلُوْنَ الَّذِیْ هُوَ اَدْنٰی بِالَّذِیْ هُوَ خَیْرٌ ؕ اِهْبِطُوْا مِصْرًا فَاِنَّ لَكُمْ مَّا سَاَلْتُمْ ؕ وَضُرِبَتْ عَلَیْهِمُ الذِّلَّةُ وَالْمَسْكَنَةُ ۗ وَبَآءُوْ بِغَضَبٍ مِّنَ اللّٰهِ ؕ ذٰلِكَ بِاَنَّهُمْ كَانُوْا یَكْفُرُوْنَ بِاٰیٰتِ اللّٰهِ وَیَقْتُلُوْنَ النَّبِیّٖنَ بِغَیْرِ الْحَقِّ ؕ ذٰلِكَ بِمَا عَصَوْا وَّكَانُوْا یَعْتَدُوْنَ ۟۠",
      "ur": "اور جب تم نے کہا اے موسیٰ! ہم سے ایک ہی قسم کے کھانے پر ہرگز صبر نہ ہوسکے گا، اس لئے اپنے رب سے دعا کیجیئے کہ وه ہمیں زمین کی پیداوار ساگ، ککڑی، گیہوں، مسور اور پیاز دے، آپ نے فرمایا، بہتر چیز کے بدلے ادنیٰ چیز کیوں طلب کرتے ہو! اچھا شہر میں جاؤ وہاں تمہاری چاہت کی یہ سب چیزیں ملیں گی[1] ۔ ان پر ذلت اور مسکینی ڈال دی گئی اور اللہ تعالی کا غضب لے کر وه لوٹے[2] یہ اس لئے کہ وه اللہ تعالیٰ کی آیتوں کے ساتھ کفر کرتے تھے اور نبیوں کو ناحق قتل کرتے[3] تھے، یہ ان کی نافرمانیوں اور زیادتیوں کا نتیجہ ہے۔[4]",
