      "ur": "ہم نے کہا کہ اس گائے کا ایک ٹکڑا مقتول کے جسم پر لگا دو، (وه جی اٹھے گا) اسی طرح اللہ مردوں کو زنده کرکے تمہیں تمہاری عقل مندی کے لئے اپنی نشانیاں دکھاتا ہے۔[1]",
