      "arFull": "اَفَتَطْمَعُوْنَ اَنْ یُّؤْمِنُوْا لَكُمْ وَقَدْ كَانَ فَرِیْقٌ مِّنْهُمْ یَسْمَعُوْنَ كَلٰمَ اللّٰهِ ثُمَّ یُحَرِّفُوْنَهٗ مِنْ بَعْدِ مَا عَقَلُوْهُ وَهُمْ یَعْلَمُوْنَ ۟",
      "ur": "(مسلمانو!) کیا تمہاری خواہش ہے کہ یہ لوگ ایماندار بن جائیں، حاﻻنکہ ان میں ایسے لوگ بھی جو کلام اللہ کو سن کر، عقل وعلم والے ہوتے ہوئے، پھر بھی بدل ڈاﻻ کرتے ہیں۔[1]",
