      "arFull": "یٰۤاَیُّهَا الَّذِیْنَ اٰمَنُوْا لَا تَقُوْلُوْا رَاعِنَا وَقُوْلُوا انْظُرْنَا وَاسْمَعُوْا ؕ وَلِلْكٰفِرِیْنَ عَذَابٌ اَلِیْمٌ ۟",
      "ur": "اے ایمان والو! تم (نبی صلی اللہ علیہ وسلم کو) “راعنا” نہ کہا کرو، بلکہ “انظرنا” کہو[1] یعنی ہماری طرف دیکھئے اور سنتے رہا کرو اور کافروں کے لئے دردناک عذاب ہے",
      "en": "O you who have believed, say not [to Allāh's Messenger], \"Rāʿinā\" but say, \"Unẓurnā\"[35] and listen. And for the disbelievers is a painful punishment.",
