      "arFull": "وَقَالُوْا كُوْنُوْا هُوْدًا اَوْ نَصٰرٰی تَهْتَدُوْا ؕ قُلْ بَلْ مِلَّةَ اِبْرٰهٖمَ حَنِیْفًا ؕ وَمَا كَانَ مِنَ الْمُشْرِكِیْنَ ۟",
