      "arFull": "وَلَىِٕنْ اَتَیْتَ الَّذِیْنَ اُوْتُوا الْكِتٰبَ بِكُلِّ اٰیَةٍ مَّا تَبِعُوْا قِبْلَتَكَ ۚ وَمَاۤ اَنْتَ بِتَابِعٍ قِبْلَتَهُمْ ۚ وَمَا بَعْضُهُمْ بِتَابِعٍ قِبْلَةَ بَعْضٍ ؕ وَلَىِٕنِ اتَّبَعْتَ اَهْوَآءَهُمْ مِّنْ بَعْدِ مَا جَآءَكَ مِنَ الْعِلْمِ ۙ اِنَّكَ اِذًا لَّمِنَ الظّٰلِمِیْنَ ۟ۘ",
      "ur": "اور آپ اگرچہ اہل کتاب کو تمام دلیلیں دے دیں لیکن وه آپ کے قبلے کی پیروی نہیں کریں گے[1] اور نہ آپ ان کے قبلے کو ماننے والے ہیں[2] اور نہ یہ آپس میں ایک دوسرے کے قبلے کو ماننے والے ہیں[3] اور اگر آپ باوجودیکہ آپ کے پاس علم آچکا پھر بھی ان کی خواہشوں کے پیچھے لگ جائیں تو بالیقین آپ بھی ﻇالموں میں سے ہوجائیں گے۔[4]",
      "en": "And if you brought to those who were given the Scripture every sign, they would not follow your qiblah. Nor will you be a follower of their qiblah. Nor would they be followers of one another's qiblah. So if you were to follow their desires after what has come to you of knowledge, indeed, you would then be among the wrongdoers.",
