      "arFull": "وَمَثَلُ الَّذِیْنَ كَفَرُوْا كَمَثَلِ الَّذِیْ یَنْعِقُ بِمَا لَا یَسْمَعُ اِلَّا دُعَآءً وَّنِدَآءً ؕ صُمٌّۢ بُكْمٌ عُمْیٌ فَهُمْ لَا یَعْقِلُوْنَ ۟",
