      "arFull": "اُولٰٓىِٕكَ الَّذِیْنَ اشْتَرَوُا الضَّلٰلَةَ بِالْهُدٰی وَالْعَذَابَ بِالْمَغْفِرَةِ ۚ فَمَاۤ اَصْبَرَهُمْ عَلَی النَّارِ ۟",
