      "ur": "اے ایمان والو! تم پر مقتولوں کا قصاص لینا فرض کیا گیا ہے، آزاد آزاد کے بدلے، غلام غلام کے بدلے، عورت عورت کے بدلے[1] ۔ ہاں جس کسی کو اس کے بھائی کی طرف سے کچھ معافی دے دی جائے اسے بھلائی کی اتباع کرنی چاہئے اور آسانی کے ساتھ دیت ادا کرنی چاہئے[2]۔ تمہارے رب کی طرف سے یہ تخفیف اور رحمت[3] ہے اس کے بعد بھی جو سرکشی کرے اسے درد ناک عذاب ہوگا۔[4]",
