      "number": 179,
      "arFull": "وَلَكُمْ فِی الْقِصَاصِ حَیٰوةٌ یّٰۤاُولِی الْاَلْبَابِ لَعَلَّكُمْ تَتَّقُوْنَ ۟",
      "ur": "عقلمندو! قصاص میں تمہارے لئے زندگی ہے اس باعﺚ تم (قتل ناحق سے) رکو گے۔[1]",
