      "number": 180,
      "arFull": "كُتِبَ عَلَیْكُمْ اِذَا حَضَرَ اَحَدَكُمُ الْمَوْتُ اِنْ تَرَكَ خَیْرَا ۖۚ لْوَصِیَّةُ لِلْوَالِدَیْنِ وَالْاَقْرَبِیْنَ بِالْمَعْرُوْفِ ۚ حَقًّا عَلَی الْمُتَّقِیْنَ ۟ؕ",
      "ur": "تم پر فرض کر دیا گیا ہے کہ جب تم میں سے کوئی مرنے لگے اور مال چھوڑ جاتا ہو تو اپنے ماں باپ اور قرابت داروں کے لئے اچھائی کے ساتھ وصیت کرجائے[1] ، پرہیزگاروں پر یہ حق اور ﺛابت ہے۔",
