      "arFull": "اَیَّامًا مَّعْدُوْدٰتٍ ؕ فَمَنْ كَانَ مِنْكُمْ مَّرِیْضًا اَوْ عَلٰی سَفَرٍ فَعِدَّةٌ مِّنْ اَیَّامٍ اُخَرَ ؕ وَعَلَی الَّذِیْنَ یُطِیْقُوْنَهٗ فِدْیَةٌ طَعَامُ مِسْكِیْنٍ ؕ فَمَنْ تَطَوَّعَ خَیْرًا فَهُوَ خَیْرٌ لَّهٗ ؕ وَاَنْ تَصُوْمُوْا خَیْرٌ لَّكُمْ اِنْ كُنْتُمْ تَعْلَمُوْنَ ۟",
