      "number": 187,
      "arFull": "اُحِلَّ لَكُمْ لَیْلَةَ الصِّیَامِ الرَّفَثُ اِلٰی نِسَآىِٕكُمْ ؕ هُنَّ لِبَاسٌ لَّكُمْ وَاَنْتُمْ لِبَاسٌ لَّهُنَّ ؕ عَلِمَ اللّٰهُ اَنَّكُمْ كُنْتُمْ تَخْتَانُوْنَ اَنْفُسَكُمْ فَتَابَ عَلَیْكُمْ وَعَفَا عَنْكُمْ ۚ فَالْـٰٔنَ بَاشِرُوْهُنَّ وَابْتَغُوْا مَا كَتَبَ اللّٰهُ لَكُمْ ۪ وَكُلُوْا وَاشْرَبُوْا حَتّٰی یَتَبَیَّنَ لَكُمُ الْخَیْطُ الْاَبْیَضُ مِنَ الْخَیْطِ الْاَسْوَدِ مِنَ الْفَجْرِ ۪ ثُمَّ اَتِمُّوا الصِّیَامَ اِلَی الَّیْلِ ۚ وَلَا تُبَاشِرُوْهُنَّ وَاَنْتُمْ عٰكِفُوْنَ ۙ فِی الْمَسٰجِدِ ؕ تِلْكَ حُدُوْدُ اللّٰهِ فَلَا تَقْرَبُوْهَا ؕ كَذٰلِكَ یُبَیِّنُ اللّٰهُ اٰیٰتِهٖ لِلنَّاسِ لَعَلَّهُمْ یَتَّقُوْنَ ۟",
      "ur": "روزے کی راتوں میں اپنی بیویوں سے ملنا تمہارے لئے حلال کیا گیا، وه تمہارا لباس ہیں اور تم ان کے لباس ہو، تمہاری پوشیده خیانتوں کا اللہ تعالیٰ کو علم ہے، اس نے تمہاری توبہ قبول فرما کر تم سے درگزر فرمالیا، اب تمہیں ان سے مباشرت کی اور اللہ تعالیٰ کی لکھی ہوئی چیز کو تلاش کرنے کی اجازت ہے، تم کھاتے پیتے رہو یہاں تک کہ صبح کا سفید دھاگہ سیاه دھاگے سے ﻇاہر ہوجائے[1] ۔ پھر رات تک روزے کو پورا کرو[2] اور عورتوں سے اس وقت مباشرت نہ کرو جب کہ تم مسجدوں میں اعتکاف میں ہو[3]۔ یہ اللہ تعالیٰ کی حدود ہیں، تم ان کے قریب بھی نہ جاؤ۔ اسی طرح اللہ تعالیٰ اپنی آیتیں لوگوں کے لئے بیان فرماتا ہے تاکہ وه بچیں",
      "en": "It has been made permissible for you the night preceding fasting to go to your wives [for sexual relations]. They are a clothing for you and you are a clothing[67] for them. Allāh knows that you used to deceive yourselves,[68] so He accepted your repentance and forgave you. So now, have relations with them and seek that which Allāh has decreed for you [i.e., offspring]. And eat and drink until the white thread of dawn becomes distinct to you from the black thread [of night]. Then complete the fast until the night [i.e., sunset]. And do not have relations with them as long as you are staying for worship in the mosques. These are the limits [set by] Allāh, so do not approach them. Thus does Allāh make clear His verses [i.e., ordinances] to the people that they may become righteous.",
