      "number": 196,
      "arFull": "وَاَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلّٰهِ ؕ فَاِنْ اُحْصِرْتُمْ فَمَا اسْتَیْسَرَ مِنَ الْهَدْیِ ۚ وَلَا تَحْلِقُوْا رُءُوْسَكُمْ حَتّٰی یَبْلُغَ الْهَدْیُ مَحِلَّهٗ ؕ فَمَنْ كَانَ مِنْكُمْ مَّرِیْضًا اَوْ بِهٖۤ اَذًی مِّنْ رَّاْسِهٖ فَفِدْیَةٌ مِّنْ صِیَامٍ اَوْ صَدَقَةٍ اَوْ نُسُكٍ ۚ فَاِذَاۤ اَمِنْتُمْ ۥ فَمَنْ تَمَتَّعَ بِالْعُمْرَةِ اِلَی الْحَجِّ فَمَا اسْتَیْسَرَ مِنَ الْهَدْیِ ۚ فَمَنْ لَّمْ یَجِدْ فَصِیَامُ ثَلٰثَةِ اَیَّامٍ فِی الْحَجِّ وَسَبْعَةٍ اِذَا رَجَعْتُمْ ؕ تِلْكَ عَشَرَةٌ كَامِلَةٌ ؕ ذٰلِكَ لِمَنْ لَّمْ یَكُنْ اَهْلُهٗ حَاضِرِی الْمَسْجِدِ الْحَرَامِ ؕ وَاتَّقُوا اللّٰهَ وَاعْلَمُوْۤا اَنَّ اللّٰهَ شَدِیْدُ الْعِقَابِ ۟۠",
      "ur": "حج اور عمرے کو اللہ تعالیٰ کے لئے پورا کرو[1] ، ہاں اگر تم روک لئے جاؤ تو جو قربانی میسر ہو، اسے کرڈالو[2] اور اپنے سر نہ منڈواؤ جب تک کہ قربانی قربان گاه تک نہ پہنچ جائے[3] البتہ تم میں سے جو بیمار ہو، یا اس کے سر میں کوئی تکلیف ہو (جس کی وجہ سے سر منڈالے) تو اس پر فدیہ ہے، خواه روزے رکھ لے، خواه صدقہ دے دے، خواه قربانی کرے[4] پس جب تم امن کی حالت میں ہوجاؤ تو جو شخص عمرے سے لے کر حج تک تمتع کرے، پس اسے جو قربانی میسر ہو اسے کر ڈالے، جسے طاقت ہی نہ ہو وه تین روزے تو حج کے دنوں میں رکھ لے اور سات واپسی میں[5]، یہ پورے دس ہوگئے۔ یہ حکم ان کے لئے ہے جو مسجد حرام کے رہنے والے نہ ہوں[6]، لوگو! اللہ سے ڈرتے رہو اور جان لو کہ اللہ تعالیٰ سخت عذاب واﻻ ہے۔",
      "en": "And complete the ḥajj and ʿumrah for Allāh. But if you are prevented, then [offer] what can be obtained with ease of sacrificial animals. And do not shave your heads until the sacrificial animal has reached its place of slaughter. And whoever among you is ill or has an ailment of the head [making shaving necessary must offer] a ransom of fasting [three days] or charity[71] or sacrifice.[72] And when you are secure,[73] then whoever performs ʿumrah [during the ḥajj months][74] followed by ḥajj [offers] what can be obtained with ease of sacrificial animals. And whoever cannot find [or afford such an animal] - then a fast of three days during ḥajj and of seven when you have returned [home]. Those are ten complete [days]. This is for those whose family is not in the area of al-Masjid al-Ḥarām. And fear Allāh and know that Allāh is severe in penalty.",
