      "number": 211,
      "arFull": "سَلْ بَنِیْۤ اِسْرَآءِیْلَ كَمْ اٰتَیْنٰهُمْ مِّنْ اٰیَةٍۭ بَیِّنَةٍ ؕ وَمَنْ یُّبَدِّلْ نِعْمَةَ اللّٰهِ مِنْ بَعْدِ مَا جَآءَتْهُ فَاِنَّ اللّٰهَ شَدِیْدُ الْعِقَابِ ۟",
