      "arFull": "یَسْـَٔلُوْنَكَ مَاذَا یُنْفِقُوْنَ ؕ۬ قُلْ مَاۤ اَنْفَقْتُمْ مِّنْ خَیْرٍ فَلِلْوَالِدَیْنِ وَالْاَقْرَبِیْنَ وَالْیَتٰمٰی وَالْمَسٰكِیْنِ وَابْنِ السَّبِیْلِ ؕ وَمَا تَفْعَلُوْا مِنْ خَیْرٍ فَاِنَّ اللّٰهَ بِهٖ عَلِیْمٌ ۟",
      "ur": "آپ سے پوچھتے ہیں کہ وه کیا خرچ کریں؟ آپ کہہ دیجیئے جو مال تم خرچ کرو وه ماں باپ کے لئے ہے اور رشتہداروں اور یتیموں اور مسکینوں اور مسافروں کے لئے ہے[1] اور تم جو کچھ بھلائی کرو گے اللہ تعالیٰ کو اس کا علم ہے۔",
      "en": "They ask you, [O Muḥammad], what they should spend. Say, \"Whatever you spend of good is [to be] for parents and relatives and orphans and the needy and the traveler. And whatever you do of good - indeed, Allāh is Knowing of it.\"",
