      "arFull": "كُتِبَ عَلَیْكُمُ الْقِتَالُ وَهُوَ كُرْهٌ لَّكُمْ ۚ وَعَسٰۤی اَنْ تَكْرَهُوْا شَیْـًٔا وَّهُوَ خَیْرٌ لَّكُمْ ۚ وَعَسٰۤی اَنْ تُحِبُّوْا شَیْـًٔا وَّهُوَ شَرٌّ لَّكُمْ ؕ وَاللّٰهُ یَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُوْنَ ۟۠",
      "ur": "تم پر جہاد فرض کیا گیا گو وه تمہیں دشوار معلوم ہو، ممکن ہے کہ تم کسی چیز کو بری جانو اور دراصل وہی تمہارے لئے بھلی ہو اور یہ بھی ممکن ہے کہ تم کسی چیز کو اچھی سمجھو، حاﻻنکہ وه تمہارے لئے بری ہو، حقیقی علم اللہ ہی کو ہے، تم محض بےخبر ہو۔[1]",
