      "number": 219,
      "arFull": "یَسْـَٔلُوْنَكَ عَنِ الْخَمْرِ وَالْمَیْسِرِ ؕ قُلْ فِیْهِمَاۤ اِثْمٌ كَبِیْرٌ وَّمَنَافِعُ لِلنَّاسِ ؗ وَاِثْمُهُمَاۤ اَكْبَرُ مِنْ نَّفْعِهِمَا ؕ وَیَسْـَٔلُوْنَكَ مَاذَا یُنْفِقُوْنَ ؕ۬ قُلِ الْعَفْوَؕ كَذٰلِكَ یُبَیِّنُ اللّٰهُ لَكُمُ الْاٰیٰتِ لَعَلَّكُمْ تَتَفَكَّرُوْنَ ۟ۙ",
      "ur": "لوگ آپ سے شراب اور جوئے کا مسئلہ پوچھتے ہیں، آپ کہہ دیجیئے ان دونوں میں بہت بڑا گناه ہے[1] اور لوگوں کو اس سے دنیاوی فائده بھی ہوتا ہے، لیکن ان کا گناه ان کے نفع سے بہت زیاده ہے[2]۔ آپ سے یہ بھی دریافت کرتے ہیں کہ کیا کچھ خرچ کریں؟ تو آپ کہہ دیجیئے حاجت سے زائد چیز[3]، اللہ تعالیٰ اسی طرح اپنے احکام صاف صاف تمہارے لئے بیان فرما رہا ہے، تاکہ تم سوچ سمجھ سکو۔",
      "en": "They ask you about wine[80] and gambling. Say, \"In them is great sin and [yet, some] benefit for people. But their sin is greater than their benefit.\" And they ask you what they should spend. Say, \"The excess [beyond needs].\" Thus Allāh makes clear to you the verses [of revelation] that you might give thought",
