      "number": 222,
      "arFull": "وَیَسْـَٔلُوْنَكَ عَنِ الْمَحِیْضِ ؕ قُلْ هُوَ اَذًی ۙ فَاعْتَزِلُوا النِّسَآءَ فِی الْمَحِیْضِ ۙ وَلَا تَقْرَبُوْهُنَّ حَتّٰی یَطْهُرْنَ ۚ فَاِذَا تَطَهَّرْنَ فَاْتُوْهُنَّ مِنْ حَیْثُ اَمَرَكُمُ اللّٰهُ ؕ اِنَّ اللّٰهَ یُحِبُّ التَّوَّابِیْنَ وَیُحِبُّ الْمُتَطَهِّرِیْنَ ۟",
