      "arFull": "وَالْمُطَلَّقٰتُ یَتَرَبَّصْنَ بِاَنْفُسِهِنَّ ثَلٰثَةَ قُرُوْٓءٍ ؕ وَلَا یَحِلُّ لَهُنَّ اَنْ یَّكْتُمْنَ مَا خَلَقَ اللّٰهُ فِیْۤ اَرْحَامِهِنَّ اِنْ كُنَّ یُؤْمِنَّ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ ؕ وَبُعُوْلَتُهُنَّ اَحَقُّ بِرَدِّهِنَّ فِیْ ذٰلِكَ اِنْ اَرَادُوْۤا اِصْلَاحًا ؕ وَلَهُنَّ مِثْلُ الَّذِیْ عَلَیْهِنَّ بِالْمَعْرُوْفِ ۪ وَلِلرِّجَالِ عَلَیْهِنَّ دَرَجَةٌ ؕ وَاللّٰهُ عَزِیْزٌ حَكِیْمٌ ۟۠",
