      "number": 231,
      "arFull": "وَاِذَا طَلَّقْتُمُ النِّسَآءَ فَبَلَغْنَ اَجَلَهُنَّ فَاَمْسِكُوْهُنَّ بِمَعْرُوْفٍ اَوْ سَرِّحُوْهُنَّ بِمَعْرُوْفٍ ۪ وَلَا تُمْسِكُوْهُنَّ ضِرَارًا لِّتَعْتَدُوْا ۚ وَمَنْ یَّفْعَلْ ذٰلِكَ فَقَدْ ظَلَمَ نَفْسَهٗ ؕ وَلَا تَتَّخِذُوْۤا اٰیٰتِ اللّٰهِ هُزُوًا ؗ وَاذْكُرُوْا نِعْمَتَ اللّٰهِ عَلَیْكُمْ وَمَاۤ اَنْزَلَ عَلَیْكُمْ مِّنَ الْكِتٰبِ وَالْحِكْمَةِ یَعِظُكُمْ بِهٖ ؕ وَاتَّقُوا اللّٰهَ وَاعْلَمُوْۤا اَنَّ اللّٰهَ بِكُلِّ شَیْءٍ عَلِیْمٌ ۟۠",
      "ur": "جب تم عورتوں کو طلاق دو اور وه اپنی عدت ختم کرنے پر آئیں تو اب انہیں اچھی طرح بساؤ، یا بھلائی کے ساتھ الگ کردو[1] اور انہیں تکلیف پہنچانے کی غرض سے ﻇلم وزیادتی کے لئے نہ روکو، جو شخص ایسا کرے اس نے اپنی جان پر ﻇلم کیا۔ تم اللہ کے احکام کو ہنسی کھیل نہ[2] بناؤ اور اللہ کا احسان جو تم پر ہے یاد کرو اور جو کچھ کتاب وحکمت اس نے نازل فرمائی ہے جس سے تمہیں نصیحت کر رہا ہے، اسے بھی۔ اور اللہ تعالیٰ سے ڈرتے رہا کرو اور جان رکھو کہ اللہ تعالیٰ ہر چیز کو جانتا ہے",
