      "arFull": "وَاِذَا طَلَّقْتُمُ النِّسَآءَ فَبَلَغْنَ اَجَلَهُنَّ فَلَا تَعْضُلُوْهُنَّ اَنْ یَّنْكِحْنَ اَزْوَاجَهُنَّ اِذَا تَرَاضَوْا بَیْنَهُمْ بِالْمَعْرُوْفِ ؕ ذٰلِكَ یُوْعَظُ بِهٖ مَنْ كَانَ مِنْكُمْ یُؤْمِنُ بِاللّٰهِ وَالْیَوْمِ الْاٰخِرِ ؕ ذٰلِكُمْ اَزْكٰی لَكُمْ وَاَطْهَرُ ؕ وَاللّٰهُ یَعْلَمُ وَاَنْتُمْ لَا تَعْلَمُوْنَ ۟",
      "ur": "اور جب تم اپنی عورتوں کو طلاق دو اور وه اپنی عدت پوری کرلیں تو انہیں ان کے خاوندوں سے نکاح کرنے سے نہ روکو جب کہ وه آپس میں دستور کے مطابق رضامند ہوں[1] ۔ یہ نصیحت انہیں کی جاتی ہے جنہیں تم میں سے اللہ تعالیٰ پر اور قیامت کے دن پر یقین وایمان ہو، اس میں تمہاری بہترین صفائی اور پاکیزگی ہے۔ اللہ تعالیٰ جانتا ہے اور تم نہیں جانتے۔",
      "en": "And when you divorce women[91] and they have fulfilled their term, do not prevent them from remarrying their [former] husbands if they [i.e., all parties] agree among themselves on an acceptable basis. That is instructed to whoever of you believes in Allāh and the Last Day. That is better for you and purer, and Allāh knows and you know not.",
