      "arFull": "وَالَّذِیْنَ یُتَوَفَّوْنَ مِنْكُمْ وَیَذَرُوْنَ اَزْوَاجًا یَّتَرَبَّصْنَ بِاَنْفُسِهِنَّ اَرْبَعَةَ اَشْهُرٍ وَّعَشْرًا ۚ فَاِذَا بَلَغْنَ اَجَلَهُنَّ فَلَا جُنَاحَ عَلَیْكُمْ فِیْمَا فَعَلْنَ فِیْۤ اَنْفُسِهِنَّ بِالْمَعْرُوْفِ ؕ وَاللّٰهُ بِمَا تَعْمَلُوْنَ خَبِیْرٌ ۟",
