      "number": 235,
      "arFull": "وَلَا جُنَاحَ عَلَیْكُمْ فِیْمَا عَرَّضْتُمْ بِهٖ مِنْ خِطْبَةِ النِّسَآءِ اَوْ اَكْنَنْتُمْ فِیْۤ اَنْفُسِكُمْ ؕ عَلِمَ اللّٰهُ اَنَّكُمْ سَتَذْكُرُوْنَهُنَّ وَلٰكِنْ لَّا تُوَاعِدُوْهُنَّ سِرًّا اِلَّاۤ اَنْ تَقُوْلُوْا قَوْلًا مَّعْرُوْفًا ؕ۬ وَلَا تَعْزِمُوْا عُقْدَةَ النِّكَاحِ حَتّٰی یَبْلُغَ الْكِتٰبُ اَجَلَهٗ ؕ وَاعْلَمُوْۤا اَنَّ اللّٰهَ یَعْلَمُ مَا فِیْۤ اَنْفُسِكُمْ فَاحْذَرُوْهُ ۚ وَاعْلَمُوْۤا اَنَّ اللّٰهَ غَفُوْرٌ حَلِیْمٌ ۟۠",
      "ur": "تم پر اس میں کوئی گناه نہیں کہ تم اشارةً کنایتہً ان عورتوں سے نکاح کی بابت کہو، یا اپنے دل میں پوشیده اراده کرو، اللہ تعالیٰ کو علم ہے کہ تم ضرور ان کو یاد کرو گے، لیکن تم ان سے پوشیده وعدے نہ کرلو[1] ہاں یہ اور بات ہے کہ تم بھلی بات بوﻻ کرو[2] اور عقد نکاح جب تک کہ عدت ختم نہ ہوجائے پختہ نہ کرو، جان رکھو کہ اللہ تعالیٰ کو تمہارے دلوں کی باتوں کا بھی علم ہے، تم اس سے خوف کھاتے رہا کرو اور یہ بھی جان رکھو کہ اللہ تعالیٰ بخشش اور علم واﻻ ہے۔",
      "en": "There is no blame upon you for that to which you [indirectly] allude concerning a proposal to women or for what you conceal within yourselves. Allāh knows that you will have them in mind. But do not promise them secretly except for saying a proper saying. And do not determine to undertake a marriage contract until the decreed period[93] reaches its end. And know that Allāh knows what is within yourselves, so beware of Him. And know that Allāh is Forgiving and Forbearing.",
