      "arFull": "لَا جُنَاحَ عَلَیْكُمْ اِنْ طَلَّقْتُمُ النِّسَآءَ مَا لَمْ تَمَسُّوْهُنَّ اَوْ تَفْرِضُوْا لَهُنَّ فَرِیْضَةً ۖۚ وَّمَتِّعُوْهُنَّ ۚ عَلَی الْمُوْسِعِ قَدَرُهٗ وَعَلَی الْمُقْتِرِ قَدَرُهٗ ۚ مَتَاعًا بِالْمَعْرُوْفِ ۚ حَقًّا عَلَی الْمُحْسِنِیْنَ ۟",
