      "arFull": "وَاِنْ طَلَّقْتُمُوْهُنَّ مِنْ قَبْلِ اَنْ تَمَسُّوْهُنَّ وَقَدْ فَرَضْتُمْ لَهُنَّ فَرِیْضَةً فَنِصْفُ مَا فَرَضْتُمْ اِلَّاۤ اَنْ یَّعْفُوْنَ اَوْ یَعْفُوَا الَّذِیْ بِیَدِهٖ عُقْدَةُ النِّكَاحِ ؕ وَاَنْ تَعْفُوْۤا اَقْرَبُ لِلتَّقْوٰی ؕ وَلَا تَنْسَوُا الْفَضْلَ بَیْنَكُمْ ؕ اِنَّ اللّٰهَ بِمَا تَعْمَلُوْنَ بَصِیْرٌ ۟",
      "ur": "اور اگر تم عورتوں کو اس سے پہلے طلاق دے دو کہ تم نے انہیں ہاتھ لگایا ہو اور تم نے ان کا مہر بھی مقرر کردیا ہو تو مقرره مہر کا آدھا مہر دے دو، یہ اور بات ہے کہ وه خود معاف کردیں[1] یا وه شخص معاف کردے جس کے ہاتھ میں نکاح کی گره ہے[2] تمہارا معاف کردینا تقویٰ سے بہت نزدیک ہے اور آپس کی فضیلت اور بزرگی کو فراموش نہ کرو، یقیناً اللہ تعالیٰ تمہارے اعمال کو دیکھ رہا ہے۔",
      "en": "And if you divorce them before you have touched them and you have already specified for them an obligation, then [give] half of what you specified - unless they forego the right or the one in whose hand is the marriage contract foregoes it. And to forego it is nearer to righteousness. And do not forget graciousness between you. Indeed Allāh, of whatever you do, is Seeing.",
