      "arFull": "وَالَّذِیْنَ یُتَوَفَّوْنَ مِنْكُمْ وَیَذَرُوْنَ اَزْوَاجًا ۖۚ وَّصِیَّةً لِّاَزْوَاجِهِمْ مَّتَاعًا اِلَی الْحَوْلِ غَیْرَ اِخْرَاجٍ ۚ فَاِنْ خَرَجْنَ فَلَا جُنَاحَ عَلَیْكُمْ فِیْ مَا فَعَلْنَ فِیْۤ اَنْفُسِهِنَّ مِنْ مَّعْرُوْفٍ ؕ وَاللّٰهُ عَزِیْزٌ حَكِیْمٌ ۟",
