      "number": 243,
      "arFull": "اَلَمْ تَرَ اِلَی الَّذِیْنَ خَرَجُوْا مِنْ دِیَارِهِمْ وَهُمْ اُلُوْفٌ حَذَرَ الْمَوْتِ ۪ فَقَالَ لَهُمُ اللّٰهُ مُوْتُوْا ۫ ثُمَّ اَحْیَاهُمْ ؕ اِنَّ اللّٰهَ لَذُوْ فَضْلٍ عَلَی النَّاسِ وَلٰكِنَّ اَكْثَرَ النَّاسِ لَا یَشْكُرُوْنَ ۟",
      "ur": "کیا تم نے انہیں نہیں دیکھا جو ہزاروں کی تعداد میں تھے اور موت کے ڈر کے مارے اپنے گھروں سے نکل کھڑے ہوئے تھے۔ اللہ تعالیٰ نے انہیں فرمایا مرجاؤ، پھر انہیں زنده کردیا[1] بے شک اللہ تعالیٰ لوگوں پر بڑا فضل واﻻ ہے، لیکن اکثر لوگ ناشکرے ہیں۔",
      "en": "Have you not considered those who left their homes in many thousands, fearing death? Allāh said to them, \"Die\"; then He restored them to life. And Allāh is the possessor of bounty for the people, but most of the people do not show gratitude.",
