      "arFull": "وَقَالَ لَهُمْ نَبِیُّهُمْ اِنَّ اللّٰهَ قَدْ بَعَثَ لَكُمْ طَالُوْتَ مَلِكًا ؕ قَالُوْۤا اَنّٰی یَكُوْنُ لَهُ الْمُلْكُ عَلَیْنَا وَنَحْنُ اَحَقُّ بِالْمُلْكِ مِنْهُ وَلَمْ یُؤْتَ سَعَةً مِّنَ الْمَالِ ؕ قَالَ اِنَّ اللّٰهَ اصْطَفٰىهُ عَلَیْكُمْ وَزَادَهٗ بَسْطَةً فِی الْعِلْمِ وَالْجِسْمِ ؕ وَاللّٰهُ یُؤْتِیْ مُلْكَهٗ مَنْ یَّشَآءُ ؕ وَاللّٰهُ وَاسِعٌ عَلِیْمٌ ۟",
      "ur": "اور انہیں ان کے نبی نے فرمایا کہ اللہ تعالیٰ نے طالوت کو تمہارا بادشاه بنا دیا ہے تو کہنے لگے بھلا اس کی ہم پر حکومت کیسے ہوسکتی ہے؟ اس سے تو بہت زیاده حقدار بادشاہت کے ہم ہیں، اس کو تو مالی کشادگی بھی نہیں دی گئی۔ نبی نے فرمایا سنو، اللہ تعالیٰ نے اسی کو تم پر برگزیده کیا ہے اور اسے علمی اور جسمانی برتری بھی عطا فرمائی ہے[1] بات یہ ہے کہ اللہ جسے چاہے اپنا ملک دے، اللہ تعالیٰ کشادگی واﻻ اور علم واﻻ ہے۔",
      "en": "And their prophet said to them, \"Indeed, Allāh has sent to you Saul as a king.\" They said, \"How can he have kingship over us while we are more worthy of kingship than him and he has not been given any measure of wealth?\" He said, \"Indeed, Allāh has chosen him over you and has increased him abundantly in knowledge and stature. And Allāh gives His sovereignty to whom He wills. And Allāh is all-Encompassing [in favor] and Knowing.\"",
