      "arFull": "اَیَوَدُّ اَحَدُكُمْ اَنْ تَكُوْنَ لَهٗ جَنَّةٌ مِّنْ نَّخِیْلٍ وَّاَعْنَابٍ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ ۙ لَهٗ فِیْهَا مِنْ كُلِّ الثَّمَرٰتِ ۙ وَاَصَابَهُ الْكِبَرُ وَلَهٗ ذُرِّیَّةٌ ضُعَفَآءُ ۪ۖ فَاَصَابَهَاۤ اِعْصَارٌ فِیْهِ نَارٌ فَاحْتَرَقَتْ ؕ كَذٰلِكَ یُبَیِّنُ اللّٰهُ لَكُمُ الْاٰیٰتِ لَعَلَّكُمْ تَتَفَكَّرُوْنَ ۟۠",
