      "ur": "صدقات کے مستحق صرف وه غربا ہیں جو اللہ کی راه میں روک دیئے گئے، جو ملک میں چل پھر نہیں سکتے[1] نادان لوگ ان کی بے سوالی کی وجہ سے انہیں مالدار خیال کرتے ہیں، آپ ان کے چہرے دیکھ کر قیافہ سے انہیں پہچان لیں گے وه لوگوں سے چمٹ کر سوال نہیں کرتے[2]، تم جو کچھ مال خرچ کرو تو اللہ تعالیٰ اس کا جاننے واﻻ ہے۔",
