      "arFull": "اَلَّذِیْنَ یَاْكُلُوْنَ الرِّبٰوا لَا یَقُوْمُوْنَ اِلَّا كَمَا یَقُوْمُ الَّذِیْ یَتَخَبَّطُهُ الشَّیْطٰنُ مِنَ الْمَسِّ ؕ ذٰلِكَ بِاَنَّهُمْ قَالُوْۤا اِنَّمَا الْبَیْعُ مِثْلُ الرِّبٰوا ۘ وَاَحَلَّ اللّٰهُ الْبَیْعَ وَحَرَّمَ الرِّبٰوا ؕ فَمَنْ جَآءَهٗ مَوْعِظَةٌ مِّنْ رَّبِّهٖ فَانْتَهٰی فَلَهٗ مَا سَلَفَ ؕ وَاَمْرُهٗۤ اِلَی اللّٰهِ ؕ وَمَنْ عَادَ فَاُولٰٓىِٕكَ اَصْحٰبُ النَّارِ ۚ هُمْ فِیْهَا خٰلِدُوْنَ ۟",
